<?php
namespace App\Http\Controllers;
use App\Models\{CorrectiveAction,Department,Incident,Inspection,Risk}; use Illuminate\Http\Request;
class ReportController extends Controller {
 public function index(Request $r){$from=$r->filled('from')?jalaliToCarbon($r->input('from')):now()->subMonths(6)->startOfMonth();$to=$r->filled('to')?jalaliToCarbon($r->input('to')):now()->endOfMonth();if(!$from)$from=now()->subMonths(6)->startOfMonth();if(!$to)$to=now()->endOfMonth();$riskByLevel=Risk::whereBetween('created_at',[$from,$to])->selectRaw('risk_level, count(*) total')->groupBy('risk_level')->pluck('total','risk_level');$incidentByType=Incident::whereBetween('occurred_at',[$from,$to])->selectRaw('type, count(*) total')->groupBy('type')->pluck('total','type');$departmentStats=Department::withCount(['users'])->get()->map(function($d)use($from,$to){$d->risks_count=Risk::where('department_id',$d->id)->whereBetween('created_at',[$from,$to])->count();$d->actions_open=CorrectiveAction::where('department_id',$d->id)->whereNotIn('status',['verified','closed'])->count();$d->inspection_avg=round((float)Inspection::where('department_id',$d->id)->whereNotNull('score')->avg('score'),1);return $d;});return view('reports.index',compact('riskByLevel','incidentByType','departmentStats','from','to'));}
 public function export(Request $r){$type=$r->validate(['type'=>'required|in:risks,incidents,actions,inspections'])['type'];$rows=match($type){'risks'=>Risk::with('department')->get()->map(fn($x)=>[$x->code,$x->title,$x->department->name,$x->assessment_method,$x->risk_score,$x->risk_level,$x->residual_score,$x->status]),'incidents'=>Incident::with('department')->get()->map(fn($x)=>[$x->code,$x->title,$x->department->name,$x->type,$x->occurred_at,$x->status]),'actions'=>CorrectiveAction::with('department','assignee')->get()->map(fn($x)=>[$x->code,$x->title,$x->department->name,$x->assignee->name,$x->due_date,$x->status]),default=>Inspection::with('department','inspector')->get()->map(fn($x)=>[$x->code,$x->title,$x->department->name,$x->inspector->name,$x->score,$x->status])};$headers=match($type){'risks'=>['کد','عنوان','واحد','روش','امتیاز اولیه','سطح','امتیاز باقیمانده','وضعیت'],'incidents'=>['کد','عنوان','واحد','نوع','زمان','وضعیت'],'actions'=>['کد','عنوان','واحد','مسئول','سررسید','وضعیت'],default=>['کد','عنوان','واحد','بازرس','امتیاز','وضعیت']};return response()->streamDownload(function()use($rows,$headers){$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$headers);foreach($rows as $row)fputcsv($out,$row);fclose($out);},"hse-{$type}-".today()->format('Y-m-d').'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
}
